// Imports
import SnackBar from "@/components/SnackBar.vue";
import AssignTask from "@/components/TaskDetailsApp/TaskPopups/AssignTask.vue";
import { format_Date } from "@/JsonFiles/DateFormate.js";
import AssignToMe from "@/components/TaskDetailsApp/TaskPopups/AssignToMe.vue";
import AssignByMe from "@/components/TaskDetailsApp/TaskPopups/AssignByMe.vue";
import { list_assign_task_or_completed } from "@/graphql/queries.js";
import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  // Components
  components: {
    SnackBar,
    AssignTask,
    AssignToMe,
    AssignByMe
  },
  // Data
  data() {
    return {
      // Table properties
      tableLoading: false,
      tableData: [],
      fixed: true,
      cardHeight: 0,
      nextToken: null,
      sortDesc: true,
      // Table headers
      headers: [{
        text: "Task Details",
        value: "task_name",
        sortable: false,
        width: "35%"
      }, {
        text: "Assigned To",
        value: "task_assign_to_name",
        sortable: false,
        width: "20%"
      }, {
        text: "Created On",
        value: "task_created_on",
        sortable: true,
        width: "15%"
      }, {
        text: "Due Date",
        value: "task_completion_date",
        sortable: true,
        width: "15%"
      }, {
        text: "Status",
        value: "task_progress_status",
        sortable: false,
        width: "15%"
      }],
      assignedHEaders: [{
        text: "Task Details",
        value: "task_name",
        sortable: false,
        width: "35%"
      }, {
        text: "Assigned By",
        value: "task_assign_by_name",
        sortable: false,
        width: "20%"
      }, {
        text: "Created On",
        value: "task_created_on",
        sortable: true,
        width: "15%"
      }, {
        text: "Due Date",
        value: "task_completion_date",
        sortable: true,
        width: "15%"
      }, {
        text: "Status",
        value: "task_progress_status",
        sortable: false,
        width: "15%"
      }],
      // Dialog states
      componentcheck: 0,
      assignPopup: false,
      taskCompletionDialog: false,
      assignByMeDialog: false,
      assignToMeDialog: false,
      rowInfo: {},
      // Filter properties
      selectStatusType: "ASSIGN_BY_ME",
      selectedStatus: "ALL",
      // Pagination properties
      pagination: {
        itemsPerPage: 20,
        page: 1
      },
      // Component data
      SnackBarComponent: {}
    };
  },
  // Lifecycle hooks
  created() {
    this.list_my_tasks();
    this.cardHeight = window.innerHeight - 200;
  },
  // Methods
  methods: {
    // Data fetching methods
    async list_my_tasks() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_assign_task_or_completed, {
          input: {
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            actions: this.selectStatusType,
            limit: 500,
            nextToken: this.nextToken,
            task_progress_status: this.selectedStatus === "ALL" ? null : this.selectedStatus
          }
        }));
        this.tableLoading = false;
        this.tableData = [];
        var response = result.data.list_assign_task_or_completed;
        this.nextToken = response.nextToken;
        let array = this.tableData.concat(response.details);
        this.tableData = array;
        const uniqueArrayOfObjects = this.tableData.filter((obj, index, self) => index === self.findIndex(o => o.task_id === obj.task_id));
        this.tableData = uniqueArrayOfObjects;
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    // Dialog management methods
    handleRowClick(item) {
      if (this.selectStatusType == "ASSIGN_BY_ME") {
        this.componentcheck = 2;
        this.rowInfo = item;
        this.assignByMeDialog = true;
      } else {
        this.componentcheck = 3;
        this.rowInfo = item;
        this.assignToMeDialog = true;
      }
    },
    assign_data() {
      this.componentcheck = 1;
      this.assignPopup = true;
    },
    // Filter methods
    filter_data() {
      this.list_my_tasks();
    },
    // Pagination methods
    handle_pagination() {
      if (this.nextToken) {
        this.list_my_tasks();
      }
    },
    // Navigation methods
    back_call() {
      this.$router.push("/DashboardView");
    },
    // Utility methods
    get_date(val) {
      return val;
    },
    fetch_value(val) {
      return format_Date(val / 1000);
    },
    // UI helper methods
    getInitials(name) {
      if (!name) return "?";
      return name.split(" ").map(n => n[0]).join("").toUpperCase().substring(0, 2);
    },
    // Styling methods
    getStatusColor(status) {
      const colors = {
        COMPLETED: "success",
        INPROGRESS: "warning",
        HOLD: "error",
        WITHDRAWN: "grey",
        WITHDRAW: "grey",
        ASSIGNED: "info"
      };
      return colors[status] || "grey";
    },
    getStatusTextColor(status) {
      return ["COMPLETED", "INPROGRESS", "HOLD"].includes(status) ? "white" : "white";
    },
    getStatusClass(status) {
      return `status-${status.toLowerCase()}`;
    },
    getStatusIcon(status) {
      const icons = {
        COMPLETED: "mdi-check-circle",
        INPROGRESS: "mdi-progress-clock",
        HOLD: "mdi-pause-circle",
        WITHDRAWN: "mdi-cancel",
        WITHDRAW: "mdi-cancel",
        ASSIGNED: "mdi-account-check"
      };
      return icons[status] || "mdi-help-circle";
    },
    getStatusText(status) {
      const texts = {
        COMPLETED: "Completed",
        INPROGRESS: "In Progress",
        HOLD: "On Hold",
        WITHDRAWN: "Withdrawn",
        WITHDRAW: "Withdrawn",
        ASSIGNED: "Assigned"
      };
      return texts[status] || status;
    },
    // Notification methods
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.assignByMeDialog = false;
      this.assignToMeDialog = false;
      this.assignPopup = false;
      this.list_my_tasks();
    }
  }
};
